/**
 * @name Command injection via os.system or subprocess
 * @description Using os.system or subprocess with untrusted input can lead to command injection
 * @kind path-problem
 * @problem.severity error
 * @id py/command-injection
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // System command execution via os.system
    exists(API::CallNode call |
      call = API::moduleImport("os").getMember("system").getACall() and
      sink = call.getArg(0)
    )
    or
    // System command execution via subprocess.call
    exists(API::CallNode call |
      call = API::moduleImport("subprocess").getMember("call").getACall() and
      sink = call.getArg(0)
    )
    or
    // System command execution via subprocess.Popen
    exists(API::CallNode call |
      call = API::moduleImport("subprocess").getMember("Popen").getACall() and
      sink = call.getArg(0)
    )
    or
    // System command execution via subprocess.run
    exists(API::CallNode call |
      call = API::moduleImport("subprocess").getMember("run").getACall() and
      sink = call.getArg(0)
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection from $@.", source.getNode(), "user input"

/**
 * @name File path traversal vulnerability
 * @description Using untrusted input in file operations can lead to path traversal attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // File open operations
    exists(API::CallNode call |
      call = API::moduleImport("builtins").getMember("open").getACall() and
      sink = call.getArg(0)
    )
    or
    // os.path operations
    exists(API::CallNode call |
      call = API::moduleImport("os").getMember(["open", "remove", "unlink", "rename", "stat", "chmod", "chown"]).getACall() and
      sink = call.getArg(0)
    )
    or
    // File system access
    exists(API::CallNode call |
      call = API::moduleImport("os.path").getMember(["exists", "isfile", "isdir", "getsize"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal vulnerability from $@.", source.getNode(), "user input"

/**
 * @name Dynamic import vulnerabilities
 * @description Using __import__ or importlib with untrusted input can lead to arbitrary module loading
 * @kind path-problem
 * @problem.severity high
 * @id py/dynamic-import
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module DynamicImportConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // __import__ function
    exists(API::CallNode call |
      call = API::builtin("__import__").getACall() and
      sink = call.getArg(0)
    )
    or
    // importlib.import_module
    exists(API::CallNode call |
      call = API::moduleImport("importlib").getMember("import_module").getACall() and
      sink = call.getArg(0)
    )
  }
}

module DynamicImportFlow = TaintTracking::Global<DynamicImportConfig>;
import DynamicImportFlow::PathGraph

from DynamicImportFlow::PathNode source, DynamicImportFlow::PathNode sink
where DynamicImportFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Dynamic import from $@.", source.getNode(), "user input"

/**
 * @name Dangerous attribute manipulation
 * @description Using getattr/setattr/delattr with user-controlled input can lead to attribute manipulation
 * @kind path-problem
 * @problem.severity medium
 * @id py/dangerous-attribute-manipulation
 * @tags security
 *        external/cwe/cwe-915
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module AttributeManipulationConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // getattr with user-controlled attribute name
    exists(API::CallNode call |
      call = API::builtin("getattr").getACall() and
      sink = call.getArg(1)
    )
    or
    // setattr with user-controlled attribute name
    exists(API::CallNode call |
      call = API::builtin("setattr").getACall() and
      sink = call.getArg(1)
    )
    or
    // delattr with user-controlled attribute name
    exists(API::CallNode call |
      call = API::builtin("delattr").getACall() and
      sink = call.getArg(1)
    )
    or
    // hasattr with user-controlled attribute name
    exists(API::CallNode call |
      call = API::builtin("hasattr").getACall() and
      sink = call.getArg(1)
    )
  }
}

module AttributeManipulationFlow = TaintTracking::Global<AttributeManipulationConfig>;
import AttributeManipulationFlow::PathGraph

from AttributeManipulationFlow::PathNode source, AttributeManipulationFlow::PathNode sink
where AttributeManipulationFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Dangerous attribute manipulation from $@.", source.getNode(), "user input"
